text(await tools.exec_command({cmd:`cat > /app/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="dark">
<title>Steaming vegan ramen</title>
<style>
  html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; background: #100e0d; }
  canvas { display: block; width: 100%; height: 100%; }
</style>
</head>
<body>
<canvas role="img" aria-label="A steaming charcoal bowl of vegan ramen with golden noodles, seared tofu, shiitake mushrooms and bok choy."></canvas>
<script>
'use strict';

const canvas = document.querySelector('canvas');
const screen = canvas.getContext('2d', { alpha: false });
const still = document.createElement('canvas');
const ctx = still.getContext('2d', { alpha: false });
const motion = matchMedia('(prefers-reduced-motion: reduce)');
const glowPoints = [];
const tau = Math.PI * 2;

function random(seed) {
  return function () {
    seed = (Math.imul(1664525, seed) + 1013904223) >>> 0;
    return seed / 4294967296;
  };
}
let rnd = random(31);
const range = (a, b) => a + rnd() * (b - a);
const pick = values => values[Math.floor(rnd() * values.length)];

function gradient(c, x0, y0, x1, y1, stops) {
  const g = c.createLinearGradient(x0, y0, x1, y1);
  for (const [position, color] of stops) g.addColorStop(position, color);
  return g;
}

function ellipse(c, x, y, rx, ry, paint, angle = 0) {
  c.beginPath();
  c.ellipse(x, y, rx, ry, angle, 0, tau);
  c.fillStyle = paint;
  c.fill();
}

function ovalPath(x, y, rx, ry) {
  const p = new Path2D();
  p.ellipse(x, y, rx, ry, 0, 0, tau);
  return p;
}

function wash(c, x, y, rx, ry, stops) {
  c.save();
  c.translate(x, y);
  c.scale(rx, ry);
  const g = c.createRadialGradient(0, 0, 0, 0, 0, 1);
  for (const [position, color] of stops) g.addColorStop(position, color);
  ellipse(c, 0, 0, 1, 1, g);
  c.restore();
}

function line(c, path, color, width) {
  c.strokeStyle = color;
  c.lineWidth = width;
  c.stroke(path);
}

function polygon(points) {
  const path = new Path2D();
  points.forEach(([x, y], i) => i ? path.lineTo(x, y) : path.moveTo(x, y));
  path.closePath();
  return path;
}

function sampleEllipse(x, y, rx, ry) {
  const a = range(0, tau);
  const r = Math.sqrt(rnd());
  return [x + Math.cos(a) * rx * r, y + Math.sin(a) * ry * r];
}

function backdrop(box) {
  ctx.fillStyle = '#100e0d';
  ctx.fillRect(box.x, box.y, box.w, box.h);
  wash(ctx, 548, 335, 840, 645, [
    [0, '#3e2b22'], [.32, '#2c211c'], [.67, '#1b1715'], [1, '#100e0d']
  ]);
  wash(ctx, 548, 716, 730, 290, [
    [0, '#51352a'], [.35, '#402a22'], [.72, '#241b17'], [1, 'rgba(23,18,16,0)']
  ]);
  wash(ctx, 240, 557, 530, 294, [
    [0, 'rgba(140,83,49,.13)'], [1, 'rgba(140,83,49,0)']
  ]);

  // Uneven grain in the dark tabletop and the air behind it.
  for (let i = 0; i < 43000; i++) {
    const x = range(box.x, box.x + box.w);
    const y = range(box.y, box.y + box.h);
    const a = range(.016, .062) * Math.exp(-((x - 595) / 680) ** 2);
    ctx.fillStyle = rnd() < .55 ? 'rgba(207,156,112,' + a + ')' : 'rgba(0,0,0,' + a * 1.7 + ')';
    ctx.fillRect(x, y, range(.45, 1.75), range(.4, 1.35));
  }
  for (let i = 0; i < 7700; i++) {
    const y = range(544, Math.max(810, box.y + box.h));
    const x = range(25, 1175);
    const a = range(.012, .063) * Math.sin(x / 1200 * Math.PI);
    ctx.fillStyle = rnd() < .61 ? 'rgba(0,0,0,' + a + ')' : 'rgba(191,131,84,' + a * .75 + ')';
    ctx.fillRect(x, y, range(2, 31), range(.18, .8));
  }

  wash(ctx, 625, 703, 520, 119, [
    [0, 'rgba(4,4,5,.95)'], [.55, 'rgba(7,5,5,.75)'], [1, 'rgba(7,5,5,0)']
  ]);
  wash(ctx, 616, 717, 350, 45, [
    [0, 'rgba(4,3,3,1)'], [.62, 'rgba(5,4,4,.88)'], [1, 'rgba(5,4,4,0)']
  ]);
}

const lip = ovalPath(600, 477, 401, 169);
const inner = ovalPath(600, 470, 374, 149);
const soup = ovalPath(600, 479, 356, 133);

function vessel() {
  const foot = ovalPath(600, 697, 213, 37);
  ctx.fillStyle = gradient(ctx, 505, 675, 607, 734, [[0, '#3c3530'], [.7, '#171717'], [1, '#090909']]);
  ctx.fill(foot);
  const body = new Path2D('M200 472 C204 574 265 650 372 695 C474 741 706 745 822 697 C925 654 991 575 1000 477 Z');
  ctx.fillStyle = gradient(ctx, 223, 535, 1010, 670, [
    [0, '#151718'], [.15, '#41413a'], [.30, '#555348'], [.47, '#333b36'],
    [.64, '#232c29'], [.83, '#151b1b'], [1, '#0b0c0e']
  ]);
  ctx.fill(body);
  ctx.save();
  ctx.clip(body);
  const glaze = gradient(ctx, 0, 558, 0, 748, [
    [0, 'rgba(0,0,0,.65)'], [.28, 'rgba(12,15,14,.02)'],
    [.6, 'rgba(11,11,10,.16)'], [1, 'rgba(5,4,4,.74)']
  ]);
  ctx.fillStyle = glaze;
  ctx.fillRect(195, 535, 815, 220);
  wash(ctx, 350, 621, 153, 73, [[0, 'rgba(189,130,78,.22)'], [1, 'rgba(189,130,78,0)']]);
  wash(ctx, 647, 682, 298, 55, [[0, 'rgba(59,109,98,.12)'], [1, 'rgba(59,109,98,0)']]);

  for (let i = 0; i < 25000; i++) {
    const x = range(204, 998);
    const y = range(549, 734);
    const a = range(.05, .28) * (1 - .52 * (x - 200) / 800);
    const color = rnd() < .43 ? 'rgba(182,164,128,' + a + ')' : 'rgba(5,8,8,' + a * 1.6 + ')';
    ellipse(ctx, x, y, range(.28, 1.35), range(.19, .66), color, range(-.4, .4));
  }
  for (let i = 0; i < 51; i++) {
    const y = range(585, 724);
    const p = new Path2D();
    p.moveTo(224, y - 38);
    p.bezierCurveTo(394, y + 27, 731, y + 59, 963, y - 48);
    line(ctx, p, i % 2 ? 'rgba(175,166,128,.035)' : 'rgba(5,8,7,.13)', range(.4, 1.8));
  }
  ctx.restore();

  ctx.fillStyle = gradient(ctx, 301, 318, 783, 668, [
    [0, '#75624e'], [.22, '#453e34'], [.41, '#191b19'], [.65, '#363832'],
    [.83, '#6d6050'], [.93, '#4b463c'], [1, '#232723']
  ]);
  ctx.fill(lip);
  line(ctx, lip, '#181814', 3);
  ctx.save();
  ctx.clip(lip);
  for (let i = 0; i < 8500; i++) {
    const x = range(199, 1001);
    const y = range(308, 646);
    ellipse(ctx, x, y, range(.22, 1.3), range(.2, .7),
      rnd() < .48 ? 'rgba(222,190,143,.23)' : 'rgba(0,0,0,.32)');
  }
  const edge = new Path2D();
  edge.ellipse(600, 475, 398, 168, 0, .06, 3.43);
  line(ctx, edge, gradient(ctx, 209, 550, 1000, 584, [
    [0, '#695440'], [.27, '#b38a60'], [.52, '#8b7357'], [.77, '#524b3e'], [1, 'rgba(35,35,29,.15)']
  ]), 2.2);
  const backEdge = new Path2D();
  backEdge.ellipse(600, 477, 398, 167, 0, 3.42, 6.12);
  line(ctx, backEdge, gradient(ctx, 220, 335, 985, 410, [
    [0, '#59483a'], [.36, '#ac8763'], [.68, '#5c5043'], [1, '#37312b']
  ]), 2.4);
  ctx.restore();

  ctx.fillStyle = gradient(ctx, 0, 322, 0, 628, [
    [0, '#130f0d'], [.17, '#34251c'], [.62, '#67432a'], [1, '#201b17']
  ]);
  ctx.fill(inner);
  line(ctx, inner, gradient(ctx, 0, 323, 0, 622, [
    [0, '#261d17'], [.45, '#261e18'], [.86, '#9b7450'], [1, '#886548']
  ]), 2.3);
}

function broth() {
  ctx.fillStyle = gradient(ctx, 311, 385, 749, 601, [
    [0, '#723015'], [.26, '#aa4b1c'], [.48, '#9b3e14'], [.70, '#b9561e'], [.86, '#a24418'], [1, '#60250f']
  ]);
  ctx.fill(soup);
  ctx.save();
  ctx.clip(soup);
  for (let i = 0; i < 150; i++) {
    const [x, y] = sampleEllipse(600, 479, 365, 140);
    const size = range(12, 90);
    wash(ctx, x, y, size, size * range(.25, .57), [
      [0, pick(['rgba(239,130,40,.22)', 'rgba(71,17,5,.29)', 'rgba(255,169,56,.17)', 'rgba(134,36,9,.35)'])],
      [1, 'rgba(165,77,30,0)']
    ]);
  }
  for (let i = 0; i < 4950; i++) {
    const [x, y] = sampleEllipse(600, 479, 360, 135);
    const size = range(.35, 2.9) * (rnd() < .09 ? 2.7 : 1);
    const a = range(.11, .46);
    ellipse(ctx, x, y, size, size * range(.22, .56),
      pick(['rgba(255,177,72,', 'rgba(240,113,29,', 'rgba(104,30,6,', 'rgba(61,16,6,']) + a + ')', range(-.26, .26));
  }
  for (let i = 0; i < 270; i++) {
    const [x, y] = sampleEllipse(600, 479, 354, 134);
    const size = range(.65, 4.5);
    ellipse(ctx, x, y, size, size * .44, 'rgba(95,28,8,.43)');
    ellipse(ctx, x - size * .13, y - size * .13, size * .7, size * .27, 'rgba(255,199,101,.48)');
    if (i % 7 === 0) glowPoints.push([x, y - size * .12, size]);
  }
  for (let i = 0; i < 44; i++) {
    const [x, y] = sampleEllipse(600, 479, 353, 133);
    const p = new Path2D();
    p.moveTo(x, y);
    p.quadraticCurveTo(x + 8, y - range(2, 5), x + range(12, 27), y - range(-2, 4));
    line(ctx, p, 'rgba(255,184,84,.23)', range(.35, 1.15));
  }
  ctx.restore();
  line(ctx, soup, 'rgba(211,112,44,.6)', 1.8);
}

function noodles() {
  ctx.save();
  ctx.clip(soup);
  wash(ctx, 512, 510, 260, 112, [[0, 'rgba(69,25,8,.87)'], [1, 'rgba(81,29,9,0)']]);
  const piles = [
    [438, 465, 162, 69, 37], [631, 448, 135, 56, 31],
    [528, 502, 193, 82, 60], [639, 527, 171, 66, 51], [458, 536, 140, 59, 43]
  ];
  for (let level = 0; level < piles.length; level++) {
    const [x, y, rx, ry, count] = piles[level];
    for (let i = 0; i < count; i++) {
      const [cx, cy] = sampleEllipse(x, y, rx * .75, ry * .74);
      const length = range(28, 91);
      const tilt = range(-.99, .99);
      const pitch = range(1.6, 3.8);
      const a = range(0, tau);
      const wobble = range(4, 12);
      const path = new Path2D();
      for (let j = 0; j <= 36; j++) {
        const u = j / 36;
        const tx = (u - .5) * length * 2;
        const ty = Math.sin(u * pitch * tau + a) * wobble
          + Math.cos(u * 5 + a) * wobble * 1.25 + Math.sin(u * 11 + a) * wobble * .33;
        const px = cx + tx * Math.cos(tilt) - ty * Math.sin(tilt);
        const py = cy + (tx * Math.sin(tilt) + ty * Math.cos(tilt)) * .53;
        if (j === 0) path.moveTo(px, py);
        else path.lineTo(px, py);
      }
      const width = range(2.2, 5.5);
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.save();
      ctx.translate(.5, 1.15);
      line(ctx, path, 'rgba(63,22,5,.73)', width + 2.25);
      ctx.restore();
      const bright = rnd() > .31;
      line(ctx, path, gradient(ctx, cx - length * .85, cy - 22, cx + length * .83, cy + 22, [
        [0, 'rgba(175,80,21,.63)'],
        [.14, bright ? '#d79645' : '#ae652a'],
        [.41, bright ? '#f1bd6a' : '#d48a3a'],
        [.66, bright ? '#edb361' : '#c9772c'],
        [.90, '#c67b31'], [1, 'rgba(153,64,15,.71)']
      ]), width);
      ctx.save();
      ctx.translate(-.31, -.63);
      line(ctx, path, gradient(ctx, cx - length * .6, cy - 15, cx + length * .64, cy + 14, [
        [0, 'rgba(255,220,154,0)'], [.33, bright ? 'rgba(255,224,161,.72)' : 'rgba(251,188,106,.29)'],
        [.65, 'rgba(255,214,145,.45)'], [1, 'rgba(255,220,154,0)']
      ]), width * .33);
      ctx.restore();
    }
  }
  ctx.restore();
}

function mushroom(x, y, size, angle) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.scale(size, size);
  wash(ctx, 0, 9, 66, 38, [[0, 'rgba(42,13,6,.9)'], [1, 'rgba(42,13,6,0)']]);
  const cap = new Path2D('M-57 5 C-59 -19 -40 -33 -13 -36 C21 -43 50 -30 58 -9 C65 10 42 24 14 27 C-13 30 -49 27 -57 5Z');
  ctx.fillStyle = gradient(ctx, -33, -36, 19, 28, [
    [0, '#945632'], [.25, '#693b22'], [.45, '#522714'], [.75, '#331a14'], [1, '#21120e']
  ]);
  ctx.fill(cap);
  line(ctx, cap, '#341a10', 2);
  ctx.save();
  ctx.clip(cap);
  for (let i = 0; i < 600; i++) {
    const xx = range(-58, 63);
    const yy = range(-39, 25);
    ellipse(ctx, xx, yy, range(.22, 1.7), range(.19, .74),
      rnd() > .5 ? 'rgba(208,134,76,.27)' : 'rgba(26,9,4,.38)', range(-.65, .2));
  }
  wash(ctx, -28, -26, 56, 23, [[0, 'rgba(226,151,95,.43)'], [1, 'rgba(202,107,67,0)']]);
  ctx.restore();
  const flesh = new Path2D('M-56 3 C-39 16 -13 16 7 10 C28 3 42 -7 57 -10 C64 4 47 18 25 24 C-1 35 -43 30 -55 13Z');
  ctx.fillStyle = gradient(ctx, -18, -2, 12, 34, [
    [0, '#e7ad71'], [.45, '#a96538'], [.81, '#6d3c24'], [1, '#4a2918']
  ]);
  ctx.fill(flesh);
  ctx.save();
  ctx.clip(flesh);
  for (let i = 0; i < 42; i++) {
    const xx = -58 + i * 2.85;
    const p = new Path2D();
    p.moveTo(xx * .49 + 9, 2);
    p.quadraticCurveTo(xx * .76, 15, xx, range(17, 37));
    line(ctx, p, i % 3 === 0 ? 'rgba(246,181,117,.47)' : 'rgba(55,26,12,.57)', range(.46, 1.2));
  }
  ctx.restore();
  line(ctx, new Path2D('M-53 4 C-32 19 -5 15 9 10 C32 3 46 -8 56 -8'), 'rgba(253,186,114,.76)', 1.45);
  ctx.restore();
}

function tofu(x, y, size, angle) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.scale(size, size);
  wash(ctx, 5, 25, 69, 40, [[0, 'rgba(47,13,3,.93)'], [1, 'rgba(47,13,3,0)']]);
  const top = new Path2D('M-49 -22 Q-52 -25 -44 -28 L3 -47 Q9 -49 15 -45 L53 -23 Q58 -19 52 -15 L5 8 Q0 10 -6 7Z');
  const front = new Path2D('M-49 -23 L1 8 L2 42 Q0 46 -5 44 L-46 20 Q-50 17 -50 13 Z');
  const side = new Path2D('M1 8 L53 -17 L50 17 Q49 21 45 24 L5 44 Q2 46 1 42Z');
  for (const [face, colors] of [
    [side, ['#c58d4d', '#895026', '#62341d']],
    [front, ['#e8bb78', '#ba8549', '#865025']],
    [top, ['#f1c989', '#d79a50', '#a66a30']]
  ]) {
    ctx.fillStyle = gradient(ctx, -23, -43, 28, 43, [[0, colors[0]], [.55, colors[1]], [1, colors[2]]]);
    ctx.fill(face);
    ctx.save();
    ctx.clip(face);
    for (let i = 0; i < 1450; i++) {
      const xx = range(-52, 56);
      const yy = face === top ? range(-48, 9) : range(-26, 46);
      const size = range(.2, 1.66);
      ellipse(ctx, xx, yy, size, size * range(.38, .91),
        pick(['rgba(78,33,13,.44)', 'rgba(255,216,145,.44)', 'rgba(121,54,16,.32)']), range(-1, 1));
    }
    if (face === top) {
      for (let i = 0; i < 25; i++) {
        const xx = range(-45, 47);
        const yy = range(-43, 6);
        wash(ctx, xx, yy, range(3, 15), range(2, 7), [
          [0, pick(['rgba(114,46,11,.72)', 'rgba(148,65,19,.64)', 'rgba(238,177,90,.49)'])],
          [1, 'rgba(139,62,17,0)']
        ]);
      }
      for (let i = 0; i < 160; i++) {
        const xx = range(-44, 45);
        const yy = range(-44, 8);
        const s = range(.25, 1.6);
        ellipse(ctx, xx, yy, s, s * .57, 'rgba(74,30,12,.58)', -.24);
      }
    }
    ctx.restore();
    line(ctx, face, 'rgba(97,49,20,.72)', 1.25);
  }
  line(ctx, new Path2D('M-47 -23 L-6 6 Q0 9 5 6 L48 -14'), 'rgba(255,216,153,.86)', 1.3);
  line(ctx, new Path2D('M-44 -28 L3 -46 Q9 -48 14 -45 L47 -26'), 'rgba(255,218,151,.67)', 1.15);
  ctx.restore();
}

function leaf(x, y, scale, angle, hue) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.scale(scale, scale);
  const blade = new Path2D('M0 1 C-13 -9 -18 -22 -27 -31 C-42 -45 -56 -62 -52 -77 C-57 -90 -48 -102 -53 -111 C-54 -124 -37 -130 -38 -140 C-38 -152 -20 -150 -16 -164 C-10 -177 8 -169 20 -162 C39 -163 38 -150 47 -144 C62 -136 62 -125 58 -114 C65 -102 53 -94 55 -82 C56 -68 35 -60 33 -49 C22 -37 16 -13 0 1Z');
  ctx.fillStyle = gradient(ctx, -56, -129, 52, -64, [
    [0, '#273e16'], [.25, hue ? '#688441' : '#416829'], [.54, '#3b6426'],
    [.77, hue ? '#2c481b' : '#25441d'], [1, '#122515']
  ]);
  ctx.fill(blade);
  line(ctx, blade, 'rgba(20,35,13,.85)', 1.6);
  ctx.save();
  ctx.clip(blade);
  for (let i = 0; i < 590; i++) {
    const xx = range(-57, 60);
    const yy = range(-168, -26);
    ellipse(ctx, xx, yy, range(.3, 3.4), range(.19, 1.18),
      pick(['rgba(151,180,77,.24)', 'rgba(189,184,101,.15)', 'rgba(13,34,10,.29)']), range(-1, 1));
  }
  for (let i = 0; i < 13; i++) {
    const yy = -37 - i * 9.3;
    const side = i % 2 ? 1 : -1;
    const end = range(32, 60) * side;
    const vein = new Path2D();
    vein.moveTo(Math.sin(i / 3) * 3, yy);
    vein.bezierCurveTo(end * .46, yy - 4, end * .77, yy - 19, end, yy - 30);
    line(ctx, vein, 'rgba(18,44,11,.46)', range(2, 4));
    ctx.translate(-.7, -.65);
    line(ctx, vein, 'rgba(181,191,91,.31)', range(.5, 1.55));
    ctx.translate(.7, .65);
    for (let j = 0; j < 3; j++) {
      const vx = end * (.3 + j * .2);
      const vy = yy - 6 - j * 6;
      const branch = new Path2D();
      branch.moveTo(vx, vy);
      branch.quadraticCurveTo(vx + side * 13, vy - 3, vx + side * 20, vy - 14);
      line(ctx, branch, 'rgba(172,190,86,.23)', .65);
    }
  }
  ctx.restore();
  const stalk = new Path2D('M-11 9 C-17 2 -11 -17 -9 -34 C-10 -58 -5 -78 -3 -99 Q-2 -116 5 -139 C4 -117 4 -88 8 -76 C9 -53 10 -31 16 -12 Q22 0 12 8 Q2 15 -11 9Z');
  ctx.fillStyle = gradient(ctx, 4, -126, 8, 9, [
    [0, 'rgba(170,189,84,.46)'], [.35, '#81a94b'], [.7, '#adbe72'], [1, '#d8d497']
  ]);
  ctx.fill(stalk);
  line(ctx, new Path2D('M-6 6 C-11 -6 -4 -29 -4 -47 Q-4 -69 -1 -84'), 'rgba(238,230,159,.66)', 2.5);
  ctx.restore();
}

function scallion(x, y, s, angle) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  const ry = s * range(.29, .65);
  ellipse(ctx, .9, 1.5, s + 1.5, ry + 1, 'rgba(52,23,8,.72)');
  const ring = new Path2D();
  ring.ellipse(0, 0, s, ry, 0, 0, tau);
  ring.ellipse(.18, -.1, s * .60, ry * .51, 0, 0, tau);
  ctx.fillStyle = gradient(ctx, 0, -ry, 0, ry, [
    [0, pick(['#b9c873', '#a0bd56', '#d0cf89'])],
    [.56, '#719840'], [1, '#385c28']
  ]);
  ctx.fill(ring, 'evenodd');
  const edge = new Path2D();
  edge.ellipse(0, 0, s * .94, ry * .89, 0, 3.3, 5.85);
  line(ctx, edge, 'rgba(224,225,153,.71)', .84);
  ctx.restore();
}

function toppings() {
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  mushroom(379, 419, .94, -.29);
  mushroom(443, 409, .86, .13);
  mushroom(338, 455, .88, -.51);
  mushroom(397, 455, 1.07, .22);
  mushroom(459, 445, .73, -.22);

